class UniqueID {
public:
    /**
     * @brief Constructs a UniqueID by generating a unique value.
     */
    UniqueID() : m_id(generate()) {
    }

    /**
     * @brief Implicit conversion operator to uint64_t.
     * @return The unique ID as uint64_t.
     */
    constexpr operator uint64_t() const noexcept {
        return m_id;
