private:
    /// @brief Get the internal shared pointer for advanced operations.
    [[nodiscard]] std::shared_ptr<react_type> getPtr() const {
        auto ptr = m_weakPtr.lock();
        if (!ptr) [[unlikely]] {
            REACTION_THROW_NULL_POINTER("weak pointer lock failed");
