    auto unlock_shared() noexcept(noexcept(std::declval<T>().unlock_shared()))
        -> decltype(std::declval<T>().unlock_shared(), void()) {
        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
            m_mutex.unlock_shared();
        }
