 * @return React<VarExpr, const std::remove_cvref_t<SrcType>, IV, TR> Reactive constant wrapper.
 */
template <IsTrigger TR = ChangeTrig, IsInvalidation IV = KeepHandle, NonReact SrcType>
auto constVar(SrcType &&t) {
