    /// @brief Compound division assignment operator (/=)
    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && DivideAssignable<Type, U>)
    React &operator/=(const U &rhs) {
        atomicDivideAssign(*getPtr(), rhs);
