REACTION_DEFINE_ATOMIC_ASSIGN_FUNCTION(LeftShift, LeftShiftAssignOp, <<)
REACTION_DEFINE_ATOMIC_ASSIGN_FUNCTION(RightShift, RightShiftAssignOp, >>)

