    [[nodiscard]] size_t operator()(const reaction::NodeWeak &wp) const noexcept {
        try {
            if (auto ptr = wp.lock()) {
                return std::hash<reaction::ObserverNode *>()(ptr.get());
            }
            return 0;
        } catch (...) {
            return 0; // Safe exception handling
        }
    }
