class CycleDetectionCache : public PairCacheBase<NodePtr, NodePtr, bool> {
private:
    using BaseType = PairCacheBase<NodePtr, NodePtr, bool>;

public:
    CycleDetectionCache()
        : BaseType(MAX_CYCLE_CACHE_SIZE, CACHE_TTL) {}

